INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$fa53dbb2-a174-489b-803f-d7c70ef142e0$seed$, $seed$2026-02-16 13:21:57.94986+00$seed$, $seed$2026-02-16 13:21:57.94986+00$seed$, $seed$09689ca9-1653-4ce7-8532-fe8cbf7f1b99$seed$, $seed$https://staging.refugies.info$seed$, $seed$699319f5bf030a64b65230e8$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"origin": "RCO", "themes": ["Apprendre le français"], "translations": {"fr": {"content": {"abstract": "", "markdown": "### Objectif de la formation\n\n- Les formations ont pour but de favoriser l'intégration des parents d'élèves, primo-arrivants, immigrés ou étrangers hors Union européenne, volontaires, en les impliquant notamment dans la scolarité de leur enfant.\n- Attestation de suivi.\n- Validation possible selon le cas (DELF, DCL).\n\n### Contenu de la formation\n\nLes formations portent sur trois axes d'apprentissage :\n\n- l'acquisition du français (comprendre, parler, lire et écrire) ;\n- la connaissance des valeurs de la République et leur mise en œuvre dans la société française ;\n- la connaissance du fonctionnement et des attentes de l'école vis-à-vis des élèves et des parents.\n  Cette formation est assurée par des enseignants en Français Langue Seconde, des enseignants des UPE2A, ou des membres d'associations diplômés en FLE-FLS.\n\n## Conditions d'accès\n\nEtre primo-arrivants, immigres ou etrangers hors Union europeenne.", "titreMarque": "Ceci est un test de traduction", "titreInformatif": "Ceci est un test de traduction"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, NULL, $seed$e3829880-d457-49d3-9d9d-88456f843a61$seed$, $seed$publish$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$409b05e4-8e65-4f06-a5f9-ed6396809e5c$seed$, $seed$2026-02-16 13:22:34.013636+00$seed$, $seed$2026-02-16 13:22:34.013636+00$seed$, $seed$09689ca9-1653-4ce7-8532-fe8cbf7f1b99$seed$, $seed$https://staging.refugies.info$seed$, $seed$699319f5bf030a64b65230e8$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"_id": "699319f5bf030a64b65230e8", "translations": {"ru": {"content": {"abstract": "", "markdown": "### Цель обучения\n\n- Обучение направлено на содействие интеграции родителей учащихся, недавно прибывших лиц, иммигрантов или иностранцев из стран, не входящих в Европейский союз, добровольцев, путём их активного участия в образовании своего ребёнка.\n- Свидетельство об окончании курса.\n- Возможна сертификация в соответствии с ситуацией (DELF, DCL).\n\n### Содержание обучения\n\nОбучение охватывает три направления:\n\n- приобретение навыков французского языка (понимание, говорение, чтение и письмо);\n- изучение ценностей Республики и их применения в французском обществе;\n- понимание работы школы и требований, предъявляемых к учащимся и родителям.\n\nОбучение проводят преподаватели французского языка как иностранного, преподаватели классов UPE2A или сотрудники ассоциаций, имеющие дипломы в области французского языка (FLE-FLS).\n\n## Условия доступа\n\nБыть недавно прибывшим лицом, иммигрантом или иностранцем из стран, не входящих в Европейский союз.", "titreMarque": "", "titreInformatif": "Это тест перевода"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, $seed$d3d3c50c-0b52-414a-9534-652afd81aabf$seed$, NULL, $seed$translation$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$2de7c456-e856-40ea-aabc-c4a6957e5088$seed$, $seed$2026-02-16 15:12:33.667763+00$seed$, $seed$2026-02-16 15:12:33.667763+00$seed$, $seed$9aa94d11-6b40-4504-ba99-38e951e652a4$seed$, $seed$https://staging.refugies.info$seed$, $seed$699333e10742a913ca197ef8$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"origin": "RCO", "themes": ["Apprendre le français"], "translations": {"fr": {"content": {"abstract": "", "markdown": "### Objectif de la formation\n\nLes formations ont pour but de favoriser l'intégration des parents d'élèves, primo-arrivants, immigrés ou étrangers hors Union européenne, volontaires, en les impliquant notamment dans la scolarité de leur enfant.\n\n### Contenu de la formation\n\nLes formations portent sur trois axes d'apprentissage : - l'acquisition du français (comprendre, parler, lire et écrire) ; - la connaissance des valeurs de la République et leur mise en œuvre dans la société française ; - la connaissance du fonctionnement et des attentes de l'école vis-à-vis des élèves et des parents. Cette formation est assurée par des enseignants en Français Langue Seconde, des enseignants des UPE2A, ou des membres d'associations diplômés en FLE-FLS\n\n## Conditions d'accès\n\nPrimo-arrivant, refugies\nAvoir un enfant scolarise dans l etablissement ou se deroule le dispositif ou un etablissement proche.", "titreMarque": "Ouvrir l'école aux parents pour la réussite des enfants - OEPRE", "titreInformatif": "Ouvrir l'école aux parents pour la réussite des enfants - OEPRE"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, NULL, $seed$c084aa80-83ad-4354-8d7e-5a68749c94ee$seed$, $seed$publish$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$5becd5f2-43ed-4c99-9392-714e20c6f7f4$seed$, $seed$2026-02-19 15:54:27.151785+00$seed$, $seed$2026-02-19 15:54:27.151785+00$seed$, $seed$18fc7d09-52ec-4b16-b732-2e5e5d37f0a1$seed$, $seed$https://staging.refugies.info$seed$, $seed$699732320816f78eaa95b12f$seed$, $seed$published$seed$, $seed${"email": "alice@example.com", "dispositif": {"origin": "RCO", "themes": ["Apprendre le français"], "translations": {"fr": {"content": {"abstract": "", "markdown": "*(cours de français adaptés à votre niveau, pour la vie quotidienne et le travail)*\n\nCette formation vous aide à parler, comprendre et écrire en français. Vous apprenez aussi le vocabulaire du travail et les habitudes des entreprises en France.\n\n::::::::::::good-to-know\nVous pouvez commencer à tout moment de l'année. Les cours sont en groupe, selon votre niveau : débutant, intermédiaire ou avancé.\n::::::::::::\n\n## Pourquoi c'est intéressant ?\n\n::::::::::::toggle{title=\"Progresser à l'oral et à l'écrit\"}\nVous apprenez à parler français dans la vie de tous les jours : faire des courses, aller chez le médecin, parler avec l'école de vos enfants.\nVous apprenez aussi à lire et écrire des documents simples.\n::::::::::::\n\n::::::::::::toggle{title=\"Préparer votre projet professionnel\"}\nVous découvrez le vocabulaire du travail en France.\nPar exemple : comment parler à un employeur, comprendre une offre d'emploi, ou remplir un formulaire.\n::::::::::::\n\n::::::::::::toggle{title=\"Comprendre le monde du travail en France\"}\nVous apprenez comment fonctionnent les entreprises en France : les horaires, les règles, les relations avec les collègues.\n::::::::::::\n\n## Comment faire ?\n\n::::::::::::toggle{title=\"Étape 1 : Contacter l'association\"}\nAppelez le **02 48 65 67 03** ou envoyez un mail à [**contact@lerelais18.fr**](mailto\\:contact@lerelais18.fr).\n::::::::::::\n\n::::::::::::toggle{title=\"Étape 2 : Passer un entretien de positionnement\"}\nVous rencontrez un formateur. Il évalue votre niveau de français pour vous orienter vers le bon groupe.\n::::::::::::\n\n::::::::::::toggle{title=\"Étape 3 : Commencer les cours\"}\nVous intégrez un groupe (débutant, intermédiaire ou avancé) et vous commencez la formation.\n\n:::::::::::important\nLes cours ont lieu en présentiel à Bourges :\n**1 Allée Napoléon III, 18000 Bourges**\n:::::::::::\n::::::::::::", "titreMarque": "Apprendre le français pour travailler", "titreInformatif": "Apprendre le français pour travailler"}}}}}$seed$, $seed$d6378d34-3386-41bf-9698-98a8ffea6871$seed$, NULL, $seed$214e653f-718a-45e3-b8ff-6864de056b50$seed$, $seed$publish$seed$, $seed$d6378d34-3386-41bf-9698-98a8ffea6871$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$f37f23d5-59f3-4bf0-b44e-1395fecd18f2$seed$, $seed$2026-02-25 17:25:55.709156+00$seed$, $seed$2026-02-25 17:25:55.709156+00$seed$, $seed$3aa0a9ec-32ce-4f18-9d65-b2816cd6cffa$seed$, $seed$https://staging.refugies.info$seed$, $seed$699f30a36893157ee173e46b$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"origin": "RCO", "themes": ["Apprendre le français"], "translations": {"fr": {"content": {"abstract": "", "markdown": "### Objectif de la formation\n\nCe sont des formations de proximité qui visent à rendre autonomes les « apprenants » dans les différents espaces sociaux c'est-à-dire les différents lieux ou institutions de la vie courante (centres sociaux, médiathèque, CAF, CPAM, centre hospitalier, écoles, …).\nL'apprentissage de la langue française est toujours contextualisé dans le respect des valeurs de la République. Les ASL concourent à cette démarche spécifique de développement de programmes destinés à favoriser l'intégration sociale, l'accès à l'emploi, l'accès aux droits, l'accès à la culture…\n1. Permettre l'autonomie linguistique des primo-arrivants par l'apprentissage du français jusqu'au niveau A2\n2. Favoriser l'insertion professionnelle par l'acquisition de compétences linguistiques à visée professionnelle\n3. Lutter contre l'isolement et favoriser la prise ou la reprise de confiance en soi\n4. Développer l'accessibilité aux droits notamment par l'apprentissage du numérique\n5. Impliquer les participants dans la vie du centre et dans la vie locale pour faciliter le développement d'une citoyenneté active\n\n### Contenu de la formation\n\nNotre projet s'inscrit dans l'axe de l'apprentissage linguistique mais avec une dimension civique intégrée qui en fait sa spécificité.\nNotre approche d'apprentissage :\nChaque module de notre programme raconte une histoire : celle d'hommes et de femmes qui, partis de leur pays d'origine avec leurs rêves et leurs compétences, construisent pas à pas leur nouvelle vie en France. Le français devient alors non pas une matière scolaire, mais l'outil de leur émancipation, le moyen de faire entendre leur voix, de défendre leurs droits, d'accompagner leurs enfants dans leur scolarité… d'élaborer un avenir.\nContenu plus étayé et plu personnalisé pour répondre aux nouvelles exigences du passage a terme du niveau A2 obligatoire et de l'examen civique.\n\n## Conditions d'accès\n\nAucun", "titreMarque": "Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers sociolinguistiques et Compétences Pro", "titreInformatif": "Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers sociolinguistiques et Compétences Pro"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, NULL, $seed$e86f4b2f-670c-4c1b-a2be-97ee9a7ad22f$seed$, $seed$publish$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$0c87c038-8c04-48ed-886b-ea17287cd705$seed$, $seed$2026-02-25 17:27:43.94717+00$seed$, $seed$2026-02-25 17:27:43.94717+00$seed$, $seed$3aa0a9ec-32ce-4f18-9d65-b2816cd6cffa$seed$, $seed$https://staging.refugies.info$seed$, $seed$699f30a36893157ee173e46b$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"_id": "699f30a36893157ee173e46b", "themes": ["Apprendre le français"], "translations": {"fr": {"content": {"abstract": "", "markdown": "### Objectif de la formation\n\nCe sont des formations de proximité qui visent à rendre autonomes les « apprenants » dans les différents espaces sociaux c'est-à-dire les différents lieux ou institutions de la vie courante (centres sociaux, médiathèque, CAF, CPAM, centre hospitalier, écoles, …).\nL'apprentissage de la langue française est toujours contextualisé dans le respect des valeurs de la République. Les ASL concourent à cette démarche spécifique de développement de programmes destinés à favoriser l'intégration sociale, l'accès à l'emploi, l'accès aux droits, l'accès à la culture…\n1. Permettre l'autonomie linguistique des primo-arrivants par l'apprentissage du français jusqu'au niveau A2\n2. Favoriser l'insertion professionnelle par l'acquisition de compétences linguistiques à visée professionnelle\n3. Lutter contre l'isolement et favoriser la prise ou la reprise de confiance en soi\n4. Développer l'accessibilité aux droits notamment par l'apprentissage du numérique\n5. Impliquer les participants dans la vie du centre et dans la vie locale pour faciliter le développement d'une citoyenneté active\n\n### Contenu de la formation\n\nNotre projet s'inscrit dans l'axe de l'apprentissage linguistique mais avec une dimension civique intégrée qui en fait sa spécificité.\nNotre approche d'apprentissage :\nChaque module de notre programme raconte une histoire : celle d'hommes et de femmes qui, partis de leur pays d'origine avec leurs rêves et leurs compétences, construisent pas à pas leur nouvelle vie en France. Le français devient alors non pas une matière scolaire, mais l'outil de leur émancipation, le moyen de faire entendre leur voix, de défendre leurs droits, d'accompagner leurs enfants dans leur scolarité… d'élaborer un avenir.\nContenu plus étayé et plu personnalisé pour répondre aux nouvelles exigences du passage a terme du niveau A2 obligatoire et de l'examen civique.\n\n## Conditions d'accès\n\nAucun", "titreMarque": "Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers sociolinguistiques et Compétences Pro", "titreInformatif": "Actions socio-linguistiques complémentaires du CIR (ASL) - Ateliers sociolinguistiques et Compétences Pro"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, NULL, $seed$e86f4b2f-670c-4c1b-a2be-97ee9a7ad22f$seed$, $seed$publish$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$a909eb07-2569-48d0-b5d0-6e829305a65c$seed$, $seed$2026-02-25 17:29:04.021868+00$seed$, $seed$2026-02-25 17:29:04.021868+00$seed$, $seed$3aa0a9ec-32ce-4f18-9d65-b2816cd6cffa$seed$, $seed$https://staging.refugies.info$seed$, $seed$699f30a36893157ee173e46b$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"_id": "699f30a36893157ee173e46b", "translations": {"ru": {"content": {"abstract": "", "markdown": "### Цель обучения\n\nЭто программы обучения, доступные по месту жительства, которые направлены на развитие самостоятельности «учащихся» в различных социальных пространствах, то есть в различных местах и учреждениях повседневной жизни (социальные центры, медиатека, Фонд семейных пособий, Фонд медицинского страхования, больницы, школы…).\n\nОбучение французскому языку всегда осуществляется с учетом ценностей Республики. АСЛ способствуют этому специфическому подходу разработки программ, способствующих социальной интеграции, доступу к занятости, доступу к правам, доступу к культуре…\n\n1. Обеспечить языковую самостоятельность впервые прибывших мигрантов путем обучения французскому языку до уровня A2\n2. Способствовать профессиональной интеграции путем развития языковых компетенций, направленных на трудовую деятельность\n3. Снизить изоляцию и способствовать восстановлению уверенности в себе\n4. Развивать доступ к правам, в частности путем обучения цифровым навыкам\n5. Вовлечь участников в жизнь центра и местную жизнь для содействия развитию активного гражданства\n\n### Содержание обучения\n\nНаша программа основана на языковом обучении, но с интегрированным гражданским измерением, которое придает ей специфичность.\n\nНаш подход к обучению:\n\nКаждый модуль нашей программы рассказывает историю: историю мужчин и женщин, которые, покинув свою страну происхождения с мечтами и компетенциями, постепенно строят свою новую жизнь во Франции. Французский язык становится не школьным предметом, а инструментом их самоопределения, способом дать голос своим идеям, защитить свои права, помочь своим детям в учебе… и построить будущее.\n\nСодержание более детальное и более персонализированное для соответствия новым требованиям обязательного достижения уровня A2 и сдачи экзамена на гражданство.\n\n## Условия доступа\n\nОтсутствуют", "titreMarque": "", "titreInformatif": "Дополнительные социолингвистические действия ЦИР (АСЛ) — Социолингвистические мастерские и профессиональные компетенции"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, $seed$85d5ee4e-10d6-4496-818a-a3adb141f3f0$seed$, NULL, $seed$translation$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$6256b7b6-9872-4598-8daa-0ede598daea1$seed$, $seed$2026-02-25 17:29:18.350278+00$seed$, $seed$2026-02-25 17:29:18.350278+00$seed$, $seed$3aa0a9ec-32ce-4f18-9d65-b2816cd6cffa$seed$, $seed$https://staging.refugies.info$seed$, $seed$699f30a36893157ee173e46b$seed$, $seed$published$seed$, $seed${"email": "julie@example.com", "dispositif": {"_id": "699f30a36893157ee173e46b", "translations": {"ru": {"content": {"abstract": "", "markdown": "### Цель обучения\n\nЭто программы обучения, доступные по месту жительства, которые направлены на развитие самостоятельности «учащихся» в различных социальных пространствах, то есть в различных местах и учреждениях повседневной жизни (социальные центры, медиатека, Фонд семейных пособий, Фонд медицинского страхования, больницы, школы…).\n\nОбучение французскому языку всегда осуществляется с учетом ценностей Республики. АСЛ способствуют этому специфическому подходу разработки программ, способствующих социальной интеграции, доступу к занятости, доступу к правам, доступу к культуре…\n\n1. Обеспечить языковую самостоятельность впервые прибывших мигрантов путем обучения французскому языку до уровня A2\n2. Способствовать профессиональной интеграции путем развития языковых компетенций, направленных на трудовую деятельность\n3. Снизить изоляцию и способствовать восстановлению уверенности в себе\n4. Развивать доступ к правам, в частности путем обучения цифровым навыкам\n5. Вовлечь участников в жизнь центра и местную жизнь для содействия развитию активного гражданства\n\n### Содержание обучения\n\nНаша программа основана на языковом обучении, но с интегрированным гражданским измерением, которое придает ей специфичность.\n\nНаш подход к обучению:\n\nКаждый модуль нашей программы рассказывает историю: историю мужчин и женщин, которые, покинув свою страну происхождения с мечтами и компетенциями, постепенно строят свою новую жизнь во Франции. Французский язык становится не школьным предметом, а инструментом их самоопределения, способом дать голос своим идеям, защитить свои права, помочь своим детям в учебе… и построить будущее.\n\nСодержание более детальное и более персонализированное для соответствия новым требованиям обязательного достижения уровня A2 и сдачи экзамена на гражданство.\n\n## Условия доступа\n\nОтсутствуют", "titreMarque": "", "titreInformatif": "Дополнительные социолингвистические действия ЦИР (АСЛ) — Социолингвистические мастерские и профессиональные компетенции"}}}}}$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$, $seed$85d5ee4e-10d6-4496-818a-a3adb141f3f0$seed$, NULL, $seed$translation$seed$, $seed$7cd263de-3991-4c49-86dc-d37fcfb371ea$seed$) ON CONFLICT DO NOTHING;
INSERT INTO publication_records ("id", "created_at", "updated_at", "workflow_id", "target", "remote_id", "status", "payload", "published_by", "translation_record_id", "editorial_record_id", "mode", "author_id") VALUES ($seed$0c67a34d-2325-4b28-8937-6e145892f83d$seed$, $seed$2026-03-02 13:35:57.377957+00$seed$, $seed$2026-03-02 13:35:57.377957+00$seed$, $seed$26c0e650-0e85-4819-b64b-013f8a972dad$seed$, $seed$https://staging.refugies.info$seed$, $seed$69a5923cf053581e29dfa422$seed$, $seed$published$seed$, $seed${"email": "jeremie@example.com", "dispositif": {"needs": ["613721a409c5190dfa70d057", "613721a409c5190dfa70d058", "613721a409c5190dfa70d056", "613721a409c5190dfa70d079"], "theme": "63286a015d31b2c0cad9960a", "origin": "RCO", "sponsors": [{"name": "Association pour l'insertion des jeunes"}], "metadatas": {"price": {"values": [0]}, "location": ["75 - Paris", "77 - Seine-et-Marne", "78 - Yvelines", "91 - Essonne", "92 - Hauts-de-Seine", "93 - Seine-Saint-Denis", "94 - Val-de-Marne", "95 - Val-d'Oise"], "sessions": [{"endDate": "2026-07-31T23:59:59.999Z", "startDate": "2025-10-01T00:00:00.000Z"}], "commitment": {"hours": [110], "timeUnit": "hours", "amountDetails": "exactly"}, "conditions": ["school"], "frenchLevel": ["A1"], "publicStatus": ["asile", "refugie", "subsidiaire", "temporaire", "apatride"]}, "translations": {"fr": {"content": {"abstract": "Apprendre le français pour trouver un travail", "markdown": "### Objectif de la formation\n\nDonner à des personnes en difficulté professionnelle en raison de leur méconnaissance de la langue française la possibilité de se familiariser avec le langage professionnel et spécifique au monde du travail en France.\n\n### Contenu de la formation\n\nLa formation sera articulée autour des trois modules :\nCompétences linguistiques de base (Oral / Ecrit), FOS (visée professionnel et sociale), citoyenneté, etc.\nTechniques de Recherche d'Emploi : CV, lettre de motivation, recherche d'emploi / formation, monde de l'entreprise, marché du travail, etc.\nModule informatique et internet: recherche d'emploi, outils numériques, monde contemporain, ressources du territoire, mobilité, etc.\nElle est complétée par un suivi individualisé et un accompagnement à l'emploi.\n\n## Conditions d'accès\n\nCompetences linguistiques a l entree en formation :\nCECRL :\nOral : A1.1\nEcrit : A1.1", "titreMarque": "Association pour l'insertion des jeunes", "titreInformatif": "Actions socio-linguistiques complémentaires du CIR (ASL) - LING PRO : Parcours Linguistique à visée professionnelle généraliste"}}}, "secondaryThemes": ["63286a015d31b2c0cad9960e"]}}$seed$, $seed$b1bb04e3-c07b-4e22-a7eb-fea7db0a2b1c$seed$, NULL, $seed$c59742a1-54f3-4be7-ba0b-8ef52450c975$seed$, $seed$publish$seed$, $seed$b1bb04e3-c07b-4e22-a7eb-fea7db0a2b1c$seed$) ON CONFLICT DO NOTHING;
